ALTER POLICY "Public can view orcamento_items of public obras" ON public.orcamento_items TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.obras o WHERE o.id = orcamento_items.obra_id AND o.is_demo IS NOT TRUE));
ALTER POLICY "Public can view medicao_sessions of public obras" ON public.medicao_sessions TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.obras o WHERE o.id = medicao_sessions.obra_id AND o.is_demo IS NOT TRUE));
ALTER POLICY "Public can view medicao_items of public medicao_sessions" ON public.medicao_items TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.medicao_sessions ms JOIN public.obras o ON o.id = ms.obra_id WHERE ms.id = medicao_items.medicao_id AND o.is_demo IS NOT TRUE));
ALTER POLICY "Public can view aditivo_sessions of public obras" ON public.aditivo_sessions TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.obras o WHERE o.id = aditivo_sessions.obra_id AND o.is_demo IS NOT TRUE));
ALTER POLICY "Public can view aditivo_items of public aditivo_sessions" ON public.aditivo_items TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.aditivo_sessions s JOIN public.obras o ON o.id = s.obra_id WHERE s.id = aditivo_items.aditivo_id AND o.is_demo IS NOT TRUE));
ALTER POLICY "Public can view rdo_activities of public obras" ON public.rdo_activities TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.obras o WHERE o.id = rdo_activities.obra_id AND o.is_demo IS NOT TRUE));